def table_html(t):
    tid, title, sub, head, rows = t
    th = "".join(f"<th scope=col>{E(h)}</th>" for h in head)
    body = "".join("<tr>" + "".join((f'<th scope=row>{E(c)}</th>' if j == 0 else f'<td data-l="{E(head[j])}">{c}</td>') for j, c in enumerate(r)) + "</tr>" for r in rows)
    cls = " pt-wide" if len(head) > 3 else ""
    return f'''<div class="ptb{cls}" id="price-{tid}"><div class="ptb-h"><h3>{E(title)}</h3><p>{E(sub)}</p></div>
<table class="prt"><thead><tr>{th}</tr></thead><tbody>{body}</tbody></table></div>'''

def insect_html():
    """4 вида обработки — переключатель (radio, без JS) + таблицы; без переключателя на телефоне таблицы идут списком."""
    tabs = "".join(f'<input type="radio" name="ins" id="ins-{k}" class="tb-r"{" checked" if i == 0 else ""}><label for="ins-{k}" class="tb-l">{E(t.split()[0])}</label>' for i, (k, t, *_ ) in enumerate(INSECT))
    panes = "".join(f'<div class="tb-p tb-{k}">{table_html(x)}</div>' for x in INSECT for k in [x[0]])
    return f'''<div class="ptb-g"><div class="tb">{tabs}<p class="tb-cap">Тараканы, клещи, блохи, мухи, моль. «Без запаха» — препараты без выраженного запаха, дороже.</p>{panes}</div></div>'''

def tables_html(keys):
    out = []
    for k in keys:
        out.append(insect_html() if k == "insect" else table_html(ALL_TABLES[k]))
    return "".join(out)

