def where_html(names):
    seen, out = set(), []
    for n in names:
        if n in seen: continue
        seen.add(n)
        s = OBJ_SLUG.get(n)
        out.append(f'<li><a href="/obekty/{s}/">{E(n)}</a></li>' if s else f"<li>{E(n)}</li>")
    return '<ul class="wh">' + "".join(out) + "</ul>"

